app.post('/api/flows', async (req, res) => { const db = await store(); const ownerType = ['suite','case'].includes(req.body.ownerType) ? req.body.ownerType : 'global'; const suiteId = ownerType === 'suite' ? req.body.suiteId : null; const caseId = ownerType === 'case' ? req.body.caseId : null; if (ownerType === 'suite' && !db.suites.some(item => item.id === suiteId)) throw httpError(400, '请选择公共流程所属的测试套件', 'FLOW_SUITE_REQUIRED'); if (ownerType === 'case' && !db.cases.some(item => item.id === caseId)) throw httpError(400, '请选择公共流程所属的测试用例', 'FLOW_CASE_REQUIRED'); const flow = { id: randomUUID(), ownerType, suiteId, caseId, name: String(req.body.name || '新公共流程'), description: String(req.body.description || ''), parameters: Array.isArray(req.body.parameters) ? req.body.parameters : [], safety: req.body.safety || 'normal', defaults: normalizeRuntimeSettings(req.body.defaults), steps: Array.isArray(req.body.steps) ? req.body.steps : [], version: 1, currentVersion: 1, stableVersion: 1, editRevision: 1, versions: [], revisions: [], sources: {}, recordedSources: {}, executionModes: { steps: 'visual' }, createdAt: now(), updatedAt: now() }; validateMappings(flow.defaults.proxy); db.flows.push(flow); ensureVersionState(flow, 'flow', db); await persistFlowArtifacts(db, flow, true); updateCurrentVersionSnapshot(flow, 'flow', db, { source: 'create', description: '初始版本' }); await save(db); res.status(201).json(flow); });
app.put('/api/flows/:id', async (req, res) => { const db = await store(); const index = db.flows.findIndex(item => item.id === req.params.id); if (index < 0) throw httpError(404, '未找到公共流程', 'FLOW_NOT_FOUND'); const old = db.flows[index]; const nextDefaults = normalizeRuntimeSettings(req.body.defaults ?? old.defaults); validateMappings(nextDefaults.proxy); const ownerType = ['suite','case'].includes(req.body.ownerType) ? req.body.ownerType : req.body.ownerType === 'global' ? 'global' : old.ownerType || 'global'; const suiteId = ownerType === 'suite' ? (req.body.suiteId ?? old.suiteId) : null; const caseId = ownerType === 'case' ? (req.body.caseId ?? old.caseId) : null; if (ownerType === 'suite' && !db.suites.some(item => item.id === suiteId)) throw httpError(400, '请选择公共流程所属的测试套件', 'FLOW_SUITE_REQUIRED'); if (ownerType === 'case' && !db.cases.some(item => item.id === caseId)) throw httpError(400, '请选择公共流程所属的测试用例', 'FLOW_CASE_REQUIRED'); const flow = { ...old, ...req.body, ownerType, suiteId, caseId, versions: old.versions, version: old.version, currentVersion: old.currentVersion, editRevision: old.editRevision, defaults: nextDefaults, id: old.id, createdAt: old.createdAt, updatedAt: now() }; ensureExecutionSources(flow, 'flow'); if (!Array.isArray(flow.steps) || !Array.isArray(flow.parameters)) throw httpError(400, '公共流程步骤和参数必须是数组', 'INVALID_FLOW'); const base = req.body.baseVersion ? resolveAssetVersion(old, 'flow', { policy:'specific', version:Number(req.body.baseVersion), includeArchived:true }, db) : old; if (JSON.stringify(base.steps) !== JSON.stringify(flow.steps)) flow.executionModes.steps = 'visual'; const changed = JSON.stringify(assetSnapshot(base, 'flow', db)) !== JSON.stringify(assetSnapshot(flow, 'flow', db)); if (changed) { flow.revisions = [...(old.revisions || []), { version: old.version, ...assetSnapshot(old, 'flow', db), savedAt: old.updatedAt }]; commitAssetVersion(flow, 'flow', db, { source: req.body.versionSource || 'edit', description: req.body.versionDescription || '', baseVersion:req.body.baseVersion, changedScopes:versionFields.flow.filter(key=>JSON.stringify(base[key])!==JSON.stringify(flow[key])) }); } db.flows[index] = flow; await persistFlowArtifacts(db, flow, changed); if (changed) updateCurrentVersionSnapshot(flow, 'flow', db); await save(db); res.json(flow); });
app.delete('/api/flows/:id', async (req, res) => { const db = await store(); const flow = db.flows.find(item => item.id === req.params.id); if (!flow) throw httpError(404, '未找到公共流程', 'FLOW_NOT_FOUND'); const refs = []; for (const testCase of db.cases) for (const key of ['setupSteps','steps','teardownSteps']) if ((testCase[key] || []).some(step => step.kind === 'flowCall' && step.flowId === flow.id)) refs.push({ type:'case', owner:testCase, key }); for (const suite of db.suites) for (const key of ['setupSteps','teardownSteps']) if ((suite[key] || []).some(step => step.kind === 'flowCall' && step.flowId === flow.id)) refs.push({ type:'suite', owner:suite, key }); const outsideOwner = refs.filter(ref => flow.ownerType === 'global' || flow.ownerType !== ref.type || (ref.type === 'suite' ? flow.suiteId !== ref.owner.id : flow.caseId !== ref.owner.id)); if (outsideOwner.length) throw httpError(409, '公共流程仍被其他套件或用例引用，不能删除', 'FLOW_IN_USE'); for (const ref of refs) { ref.owner[ref.key] = ref.owner[ref.key].filter(step => !(step.kind === 'flowCall' && step.flowId === flow.id)); commitAssetVersion(ref.owner, ref.type, db, { source:'flow-delete', description:`删除所属公共流程 ${flow.name}`, changedScopes:[ref.key] }); updateCurrentVersionSnapshot(ref.owner, ref.type, db); } db.flows = db.flows.filter(item => item.id !== req.params.id); await save(db); res.status(204).end(); });

